package net.neoforged.neoforge.registries;public class DeferredHolder implements net.minecraft.core.Holder{private net.minecraft.core.Holder holder;public DeferredHolder(net.minecraft.core.Holder holder){this.holder=holder;}protected final void bind(boolean needed){if(holder!=null)return;throw new IllegalStateException("unbound memo");}public Object value(){bind(true);if(holder==null)throw new IllegalStateException("missing memo");return holder.value();}}
